for _ in range(int(input())):
	n = int(input())
	(arr, ll, rl, lr) = ([i for i in range(1, n + 1)], [0 for i in range(n)], [0 for i in range(n)], [])
	for i in range(n):
		(l, r) = map(int, input().split())
		lr.append([l, r])
		ll[l - 1] += 1
		rl[r - 1] += 1
	(ans, l1, r1) = ([max(ll[0], rl[0])], ll[0], rl[0])
	for i in range(1, n):
		ans.append(l1 + ll[i] - r1)
		l1 += ll[i]
		r1 += rl[i]
	ans1 = []
	for i in range(1, n + 1):
		if lr[i - 1][0] <= i <= lr[i - 1][1]:
			continue
		if ans[i - 1] == n - 1:
			ans1.append(i)
	print(len(ans1))
	for i in ans1:
		print(i)
